SELECT COUNT(*) AS delivered_orders_count
FROM orders
WHERE order_status = 'delivered';

SELECT AVG(order_total) AS average_order_value
FROM (
    SELECT order_id, SUM(payment_value) AS order_total
    FROM order_payments
    GROUP BY order_id
);

SELECT AVG(payment_installments) AS avg_installments
FROM order_payments
WHERE payment_type = 'credit_card';
